const $=id=>document.getElementById(id);
const clockParts=['hour','minute','second','millisecond','microsecond','nanosecond'];
const factors=[1,60,3600,3600000,3600000000,3600000000000];
let controller=null,menuController=null,panelController=null;
function angleValue(values,mode){if(mode==='clock')return (values.some(v=>v<0||Object.is(v,-0))?-1:1)*values.reduce((sum,v,i)=>sum+Math.abs(v)/factors[i],0)*30;return (values[0]||0)*(mode==='rad'?180/Math.PI:1)}
function angleFormat(degrees,mode,precision){if(mode==='clock'){const count=Math.max(1,clockParts.indexOf(precision)+1),factor=factors[count-1],sign=degrees<0?'-':'';let ticks=Math.round(Math.abs(degrees/30)*factor),result=[];for(let i=0;i<count;i++){const divisor=factor/factors[i],n=Math.floor(ticks/divisor);ticks-=n*divisor;result.push(i===0?String(n):String(n).padStart(i>=3?3:2,'0'))}return sign+result.join(':')}const n=Math.max(0,Math.min(9,Number(precision)||0));return (mode==='rad'?degrees*Math.PI/180:degrees).toFixed(n)+(mode==='rad'?' ':'')+unitLabel(mode==='rad'?'rad':'°')}
