function makeAngleFields(host,degrees,mode,precision,equal=false){const count=mode==='clock'&&!equal?Math.max(1,clockParts.indexOf(precision)+1):1,key=mode+':'+count+':'+equal;if(host.dataset.uiFields!==key){host.replaceChildren();for(let i=0;i<count;i++){if(i){const separator=document.createElement('span');separator.textContent=':';host.append(separator)}const input=document.createElement('input');input.type='number';input.step='any';input.inputMode='decimal';input.id=host.id==='rotationFields'?(i?'rotationPart'+i:'rotationValue'):host.id==='polarThetaFields'?(i?'polarThetaPart'+i:'polarTheta'):host.id.replace(/Fields$/,'')+(i?'Part'+i:'');input.setAttribute('aria-label',(host.id==='rotationFields'?'旋轉':'格線角度')+' '+(mode==='clock'&&!equal?clockParts[i]:''));host.append(input)}host.dataset.uiFields=key}const inputs=[...host.querySelectorAll('input')];if(host.contains(document.activeElement))return;let remaining=Math.abs(degrees)/30;inputs.forEach((input,i)=>{let value;if(equal)value=360/Math.max(.000001,degrees);else if(mode==='clock'){const previous=i===0?remaining:remaining*([1,60,60,1000,1000,1000][i]);remaining=previous-Math.floor(previous);value=i===count-1?previous:Math.floor(previous);if(i===0&&degrees<0)value=-value}else value=mode==='rad'?degrees*Math.PI/180:degrees;input.value=String(Number(value.toFixed(Math.min(9,Number(precision)||6))))})}
function drawingPreview(button,{direction='horizontal',state='solid',point=false,circle=false,directions,color='#a9c9ee',selection=false}={}){const canvas=document.createElement('canvas');canvas.width=64;canvas.height=32;canvas.className='drawing-preview';canvas.setAttribute('aria-hidden','true');button.replaceChildren(canvas);const ctx=canvas.getContext?.('2d');const background=ChipViewport.previewBackground(color);button.classList.add('drawing-preview-button');button.style.setProperty('--preview-background',background);canvas.style.backgroundColor='transparent';if(!ctx)return;if(selection){ctx.strokeStyle=color;ctx.lineWidth=2;ctx.setLineDash(ChipViewport.selectionDash(2,state==='dashed'));ctx.beginPath();ctx.moveTo(6,16);ctx.lineTo(58,16);ctx.stroke()}else{const flags=directions||{horizontal:'off',vertical:'off',diagonalUp:'off',diagonalDown:'off'};if(!directions)flags[direction]=state==='off'?'solid':state;ChipViewport.drawGrid(ctx,new ChipViewport.Camera({x:32,y:16,scale:1}),64,32,{show:true,showOrigin:false,x:100,y:100,mode:point?'point':'line',circle,pointSize:8,directions:flags,color,width:1.8,fill:true,preview:true})}}
function attachLinePreview(prefix='selectionOutline'){const select=$(prefix+'Dash');select.hidden=true;const host=document.createElement('span');host.className='line-preview-control';const toggle=document.createElement('button');toggle.type='button';toggle.setAttribute('aria-haspopup','true');toggle.setAttribute('aria-expanded','false');const menu=document.createElement('span');menu.className='line-preview-menu';menu.hidden=true;host.append(toggle,menu);select.parentNode.append(host);function paint(){const dashed=select.value==='dashed';drawingPreview(toggle,{selection:true,state:select.value,color:$(prefix+'Color').value});toggle.setAttribute('aria-label',dashed?'虛線':'實線');toggle.setAttribute('data-tooltip',dashed?'虛線':'實線');for(const button of menu.children)drawingPreview(button,{selection:true,state:button.dataset.lineStyle,color:$(prefix+'Color').value})}for(const [value,label]of [['solid','實線'],['dashed','虛線']]){const button=document.createElement('button');button.type='button';button.dataset.lineStyle=value;button.setAttribute('aria-label',label);button.setAttribute('data-tooltip',label);button.onclick=()=>{select.value=value;select.dispatchEvent(new Event('change',{bubbles:true}));menu.hidden=true;toggle.setAttribute('aria-expanded','false');paint()};menu.append(button)}toggle.onclick=()=>{menu.hidden=!menu.hidden;toggle.setAttribute('aria-expanded',String(!menu.hidden))};document.addEventListener('pointerdown',e=>{if(!host.contains(e.target)){menu.hidden=true;toggle.setAttribute('aria-expanded','false')}},true);for(const id of [prefix+'Dash',prefix+'Color'])for(const type of ['input','change'])$(id).addEventListener(type,paint);paint()}

