function attachMenu(){const title=$('projectTitle'),menu=$('fileMenu');function close(){menu.hidden=true;title.setAttribute('aria-expanded','false')}function toggle(){menu.hidden=!menu.hidden;title.setAttribute('aria-expanded',String(!menu.hidden));menu.style.top=document.querySelector('header').getBoundingClientRect().bottom+5+'px'}title.addEventListener('click',e=>{e.stopPropagation();toggle()});title.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}});document.addEventListener('pointerdown',e=>{if(!menu.hidden&&!menu.contains(e.target)&&!title.contains(e.target))close()},true);document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});menu.addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;const buttons=[...menu.querySelectorAll('button:not(:disabled)')].filter(b=>!b.closest('[hidden]')),index=buttons.indexOf(document.activeElement);e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(index+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus()});$('fileFullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(error){alert('無法切換全螢幕：'+error.message)}finally{syncFullscreen();close()}});menu.addEventListener('click',e=>{if(e.target.closest('button')?.id.startsWith('file'))close()});document.addEventListener('fullscreenchange',syncFullscreen);menuController={close,toggle};syncFullscreen();return menuController}

let uiLanguage='zh-Hant',translationNodes=[];
const english={'面板選項':'Panel options','計量單位':'Measurement Units','長度單位':'Length Units','角度單位':'Angle Units','分數／比例':'Fractions / Ratios','錨點':'Anchors','首個錨點':'First anchor','形狀':'Shape','圓形':'Circle','矩形':'Rectangle','綫條':'Lines','首個選取':'First selected','樣式':'Notation','約分':'Reduce','示例':'Example','用於縮放刻度與倍率吸附':'Used for scale graduations and snapped ratios','視圖':'View','格線':'Grid','旋轉':'Rotation','比例尺':'Scale','顯示':'Show','自動隱藏':'Auto hide','透明度':'Opacity','座標系':'Coordinates','正交系':'Cartesian','極座標':'Polar','座標系指示器':'Coordinate indicator','指示器':'Compass','長度':'Length','公制':'Metric','英制':'Imperial','單位':'Unit','小數精度':'Decimals','角度':'Angle','角度精度':'Angle precision','360° 制':'Degrees','弧度制':'Radians','時分秒':'Clock','顯示原點':'Show origin','厚':'Width','顯示格線':'Show grid','遞進':'Increment','等分':'Equal','周數':'Turns','綫模式':'Lines','點模式':'Points','大小':'Size','鋪滿':'Fill viewport','溢出':'Overflow','小時':'Hours','分鐘':'Minutes','秒':'Seconds','毫秒':'Milliseconds','微秒':'Microseconds','納秒':'Nanoseconds'};
function setLanguage(language){uiLanguage=language==='en'?'en':'zh-Hant';$('languageSelect').value=uiLanguage;document.documentElement.lang=uiLanguage;const words=uiLanguage==='en'?['Open','Save','Save As','Edit Title','Language']:['打開','保存','另存','編輯標題','語言'];['fileOpen','fileSave','fileSaveAs','fileRename'].forEach((id,i)=>$(id).querySelector('span').textContent=words[i]);$('languageLabel').textContent=words[4];for(const {node,original}of translationNodes){const text=uiLanguage==='en'?(english[original]||original):original;node.nodeValue=node.nodeValue.replace(node.nodeValue.trim(),text)}syncFullscreen();if($('localizedUnitNamesCaption'))$('localizedUnitNamesCaption').textContent=uiLanguage==='en'?'Localized unit names':'本地化量詞';syncUnitLabels();window.dispatchEvent(new Event('measurementdisplaychange'))}
function attachLanguage(){if(document.createTreeWalker)for(const root of document.querySelectorAll('.chip-ui')){const walker=document.createTreeWalker(root,4);while(walker.nextNode()){const node=walker.currentNode,original=node.nodeValue.trim();if(english[original])translationNodes.push({node,original})}}$('languageSelect').addEventListener('change',()=>setLanguage($('languageSelect').value))}
function syncFullscreen(){const button=$('fileFullscreen');if(!button)return;const active=!!document.fullscreenElement;button.setAttribute('aria-pressed',String(active));button.querySelector('span').textContent=uiLanguage==='en'?(active?'Exit Fullscreen':'Fullscreen'):(active?'退出全螢幕':'全螢幕')}
function attachPanel(){const panel=$('advanced'),pin=$('pinSettings'),button=$('viewMenuButton');let pinned=false;function layout(){document.documentElement.style.setProperty('--ui-header-bottom',(document.querySelector('header').getBoundingClientRect().bottom+8)+'px')}function setPinned(on){pinned=on;document.body.classList.toggle('ui-settings-pinned',on);pin.setAttribute('aria-pressed',String(on));panel.open=true;button.setAttribute('aria-expanded','true');layout()}function setOpen(open){if(!open&&pinned)setPinned(false);panel.open=open;button.setAttribute('aria-expanded',String(open));if(open)ChipUI.closeMenu();layout()}button.addEventListener('click',()=>setOpen(!panel.open));pin.addEventListener('click',e=>{e.preventDefault();setPinned(!pinned)});$('closeSettings').addEventListener('click',()=>setOpen(false));panel.addEventListener('toggle',()=>{if(pinned&&!panel.open)setPinned(false);button.setAttribute('aria-expanded',String(panel.open));layout()});window.addEventListener('resize',layout);layout();return {setPinned,setOpen}}

let autoHideDurations=new Map();
function attachDurationEditor(){const durations=new Map();for(const [id,bubble]of [['autoHideScale','scaleLegend'],['autoHideCompass','axisCompass']]){const field=$(id+'Duration');function sync(){const value=Math.max(0,Number(field.value)||0);durations.set(id,value);$(id).checked=value>0;$(id+'Permanent').hidden=value!==0;$(id+'DurationValue').textContent=measurements.formatNumber(value,'ms');ChipBubbles.get(bubble)?.refresh(true)}for(const type of ['input','change'])field.addEventListener(type,sync);sync()}return durations}

const unitNames={clock:['時分秒','hours:minutes:seconds'],m:['米','metre'],cm:['厘米','centimetre'],mm:['毫米','millimetre'],um:['微米','micrometre'],inch:['英寸','inch'],mil:['密耳','mil'],px:['像素','pixel'],'°':['度','degree'],rad:['弧度','radian'],h:['小時','hour'],min:['分鐘','minute'],s:['秒','second'],ms:['毫秒','millisecond'],'µs':['微秒','microsecond'],ns:['納秒','nanosecond'],count:['個','count'],ratio:['分數','fraction'],view:['視圖比','view'],'%':['百分比','%'],'‰':['千分比','‰'],'‱':['萬分比','‱']};
for(const code of ['m','cm','mm','um','inch','mil'])unitNames[code+'2']=['平方'+unitNames[code][0],unitNames[code][1]+' squared'];
function canonicalUnit(value){if(typeof value==='string'&&value.endsWith('²')){const base=canonicalUnit(value.slice(0,-1));if(Object.hasOwn(unitNames,base+'2'))return base+'2'}if(value==='µm')return 'um';if(value==='us')return 'µs';for(const [code,names] of Object.entries(unitNames))if(value===code||names.includes(value))return code;return value}
function unitLabel(code){code=canonicalUnit(code);if(!$('localizedUnitNames')?.checked)return code.endsWith('2')&&unitNames[code]?((code.slice(0,-1)==='um'?'µm':code.slice(0,-1))+'²'):code==='um'?'µm':code==='clock'?'h:min:s':code;return unitNames[code]?.[uiLanguage==='en'?1:0]||code}
